132	/*
133	 * Motion (docs/ANIMATION.md). One entrance easing for everything that arrives; exits are gentler.
134	 * lib/ease.ts reads --ease-enter for the JS animations, so this is the only place it is defined.
135	 * Only timers, progress and spinner rotation are linear.
136	 */
137	:root {
138	  --ease-enter: cubic-bezier(.22, 1, .36, 1);
139	  --ease-exit: cubic-bezier(.4, 0, .6, 1);
140	  --ease-arc: cubic-bezier(.45, 0, .2, 1);   /* X of an arc; Y uses --ease-enter */
141	  --dur-chip: 150ms;                          /* chips and small controls: 120-180 ms */
142	  --dur-window: 600ms;                        /* windows: 450-650 ms */
143	  --blink: 400ms;                             /* two blinks = 800 ms of anticipation before typing */
144	}
145	
146	/* Theme switch: colours cross-fade for a moment instead of snapping. Set by lib/theme.ts. */
147	@media (prefers-reduced-motion: no-preference) {
148	  .theme-fade,
149	  .theme-fade *,
150	  .theme-fade *::before,
151	  .theme-fade *::after {
152	    transition:
153	      background-color 240ms var(--ease-enter),
154	      color 240ms var(--ease-enter),
155	      border-color 240ms var(--ease-enter),
156	      fill 240ms var(--ease-enter),
157	      stroke 240ms var(--ease-enter);
158	  }
159	}
160	
161	/* Squash on press: 0.97 and back. Colours keep the chip timing. */
162	.press {
163	  transition:
164	    scale var(--dur-chip) var(--ease-enter),
165	    color var(--dur-chip) var(--ease-enter),
166	    background-color var(--dur-chip) var(--ease-enter),
167	    border-color var(--dur-chip) var(--ease-enter),
168	    opacity var(--dur-chip) var(--ease-enter);
169	}
170	.press:not(:disabled):active {
171	  scale: 0.97;
172	  transition-duration: 90ms;
173	}
174	
175	/* Small chips and tiles that change state. */
176	.chip-t {
177	  transition:
178	    color var(--dur-chip) var(--ease-enter),
179	    background-color var(--dur-chip) var(--ease-enter),
180	    border-color var(--dur-chip) var(--ease-enter),
181	    box-shadow var(--dur-chip) var(--ease-enter),
182	    opacity var(--dur-chip) var(--ease-enter);
183	}
184	
185	/* Story windows. Rise on an arc (Y: enter, X: arc), exit quicker and softer. */
186	.win {
187	  opacity: 0;
188	  transform: translateY(28px);
189	  translate: -14px 0;
190	  transition:
191	    opacity 300ms var(--ease-exit),
192	    transform 300ms var(--ease-exit),
193	    translate 300ms var(--ease-exit);
194	}
195	.win[data-in="true"] {
196	  opacity: 1;
197	  transform: none;
198	  translate: none;
199	  transition:
200	    opacity var(--dur-window) var(--ease-enter),
201	    transform var(--dur-window) var(--ease-enter),
202	    translate var(--dur-window) var(--ease-arc);
203	}
204	/* Staging: while another window acts, this one steps back. */
205	.win[data-in="true"][data-dim="true"] {
206	  opacity: 0.55;
207	  transition:
208	    opacity 300ms var(--ease-exit),
209	    transform var(--dur-window) var(--ease-enter),
210	    translate var(--dur-window) var(--ease-arc);
211	}
212	/* The title bar leads; the body follows about 120 ms behind it. */
213	.win-body {
214	  opacity: 0;
215	  transition: opacity 180ms var(--ease-exit);
216	}
217	.win[data-in="true"] .win-body {
218	  opacity: 1;
219	  transition: opacity 450ms var(--ease-enter) 120ms;
220	}
221	.story-group {
222	  transition: opacity 350ms var(--ease-exit);
223	}
224	.story-group[data-leaving="true"] {
225	  opacity: 0;
226	}
