228	/* Scroll reveal: the same rise, driven by lib/inview.ts. --rd is the follow-through delay. */
229	/* The sideways offset is capped at the page gutter (1rem, 1.5rem from 40rem), so an unrevealed
230	   full-width block never sticks out past the viewport and makes the page scroll sideways. */
231	.reveal {
232	  --reach: 1rem;
233	  opacity: 0;
234	  transform: translateY(28px);
235	  translate: clamp(calc(-1 * var(--reach)), var(--rx, -12px), var(--reach)) 0;
236	  transition:
237	    opacity var(--dur-window) var(--ease-enter) var(--rd, 0s),
238	    transform var(--dur-window) var(--ease-enter) var(--rd, 0s),
239	    translate var(--dur-window) var(--ease-arc) var(--rd, 0s);
240	}
241	@media (min-width: 40rem) {
242	  .reveal { --reach: 1.5rem; }
243	}
244	.reveal[data-in="true"] {
245	  opacity: 1;
246	  transform: none;
247	  translate: none;
248	}
