260	/* Things that arrive: a 2 px overshoot, then rest. --i staggers siblings by 45 ms. */
261	.settle {
262	  animation: settle 180ms var(--ease-enter) both;
263	  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
264	}
265	@keyframes settle {
266	  0% { opacity: 0; transform: translateY(6px); }
267	  65% { opacity: 1; transform: translateY(-2px); }
268	  100% { opacity: 1; transform: none; }
269	}
270	
271	/* Follow-through for things already on screen: a 2 px nudge that settles, staggered by --i. */
272	.follow {
273	  animation: follow 220ms var(--ease-enter) backwards;
274	  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
275	}
276	@keyframes follow {
277	  0% { transform: none; }
278	  40% { transform: translateY(2px); }
279	  100% { transform: none; }
280	}
281	
282	/* Exaggeration, three places only. */
283	/* 1. A failing step: one red flash, 300 ms. */
284	.flash-bad {
285	  animation: flash-bad 300ms var(--ease-exit) both;
286	}
287	@keyframes flash-bad {
288	  0% { background-color: color-mix(in srgb, var(--broken) 24%, transparent); }
289	  100% { background-color: transparent; }
290	}
291	/* 2. The winning fix: one quick lemon sweep. */
292	.sweep {
293	  background-image: linear-gradient(100deg, transparent 0%, color-mix(in srgb, var(--evidence) 75%, transparent) 45%, transparent 90%);
294	  background-size: 250% 100%;
295	  background-repeat: no-repeat;
296	  animation: sweep 520ms var(--ease-enter) both;
297	}
298	@keyframes sweep {
299	  from { background-position: 100% 0; }
300	  to { background-position: 0 0; }
301	}
302	/* 3. The verdict: a single overshoot to 1.03. */
303	.verdict-land {
304	  transform-origin: left center;
305	  animation: verdict-land 420ms var(--ease-enter) both;
306	}
307	@keyframes verdict-land {
308	  0% { opacity: 0; transform: scale(0.94); }
309	  55% { opacity: 1; transform: scale(1.03); }
310	  100% { opacity: 1; transform: scale(1); }
311	}
312	/* The one flourish when a run verifies: the lifted-r wordmark rises 4 px and settles. */
313	.lift {
314	  animation: lift 520ms var(--ease-enter);
315	}
316	@keyframes lift {
317	  0% { translate: 0 0; }
318	  40% { translate: 0 -4px; }
319	  100% { translate: 0 0; }
320	}
321	
322	/* Route change: the new page rises in. */
323	.route-enter {
324	  animation: route-in 260ms var(--ease-enter) backwards;
325	}
326	@keyframes route-in {
327	  from { opacity: 0; transform: translateY(10px); }
328	}
329	
330	/* Theme icon swap. */
331	.icon-turn {
332	  animation: icon-turn 240ms var(--ease-enter) backwards;
333	}
334	@keyframes icon-turn {
335	  from { opacity: 0; rotate: -50deg; scale: 0.6; }
336	}
337	
338	/* Secondary actions: they pause while a primary beat plays (lib/beat.ts sets data-beat). */
339	.dot-pulse {
340	  animation: dot-pulse 2.4s ease-in-out infinite;
341	}
342	@keyframes dot-pulse {
343	  50% { opacity: 0.4; }
344	}
345	[data-beat="on"] .dot-pulse {
346	  animation-play-state: paused;
347	}
