10	type TabKey = "check" | "diagnose" | "repair" | "prove";
11	
12	const TABS: { id: TabKey; label: string; icon: IconName; blurb: string }[] = [
13	  { id: "check", label: "Check", icon: "check", blurb: "Clone fresh, then install, build, test and start, stopping at the first failure." },
14	  { id: "diagnose", label: "Diagnose", icon: "diagnose", blurb: "Deterministic rules first. The model only runs when something broke." },
15	  { id: "repair", label: "Repair", icon: "repair", blurb: "The smallest change that could work, written as a patch." },
16	  { id: "prove", label: "Prove", icon: "prove", blurb: "A second container clones the same commit, applies only the fix and reruns every step. Only that counts." },
17	];
