2	import { useRun, useRuns, type RunDetail, type RunSummary } from "@/lib/api";
3	import { latestPerRepo, pickFeatured, runTag } from "@/lib/run";
4	
5	export type Problem = {
6	  key: string;
7	  title: string;
8	  body: string;
9	  /** What the run record literally says. */
10	  evidence: string;
11	  source: string;
12	  runId: string;
13	};
14	
15	export type LandingData = {
16	  loading: boolean;
17	  error: string | null;
18	  runs: RunSummary[];
19	  /** The featured run's full record: the only per-run fetch the landing page makes. */
20	  featured: RunDetail | null;
21	  featuredSummary: RunSummary | null;
22	  /** The oldest recorded run of the featured repo: where it started out. */
23	  before: RunSummary | null;
24	  latest: RunSummary[];
25	  problems: Problem[];
26	  /** One block per evaluation set and agent version, counted from the records only. */
27	  stats: StatGroup[];
28	};
29	
30	export type StatGroup = {
31	  key: string;
32	  /** "Held-out set, agent v1" */
33	  label: string;
34	  set: string | null;
35	  version: string | null;
36	  repos: number;
37	  verified: number;
38	  /** Repos whose fix only skipped tests: never counted as verified. */
39	  skipped: number;
40	  medianVerifiedS: number | null;
41	};
42	
43	const median = (xs: number[]) => {
44	  if (!xs.length) return null;
45	  const s = [...xs].sort((a, b) => a - b);
46	  const m = Math.floor(s.length / 2);
47	  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
48	};
49	
50	const PROBLEM_COPY: Record<string, { title: string; body: string }> = {
51	  toolchain: {
52	    title: "The toolchain moved",
53	    body: "A package manager tightened its defaults, and a lockfile that installed last spring now refuses to install.",
54	  },
55	  runtime: {
56	    title: "The runtime moved",
57	    body: "A native module built against an older Node never learned the newer one, so the install itself fails.",
58	  },
59	  clock: {
60	    title: "The build never finishes",
61	    body: "Some projects grew past the point where a clean build completes inside a sensible time cap, and nobody noticed because nobody builds from scratch.",
62	  },
63	};
64	
65	/** First run (newest first) that evidences each cause. The server did the matching. */
66	function findProblems(runs: RunSummary[]): Problem[] {
67	  return (["toolchain", "runtime", "clock"] as const).flatMap((key) => {
68	    for (const r of runs) {
69	      const p = r.problems?.find((x) => x.key === key);
70	      if (p) return [{ key, ...PROBLEM_COPY[key], evidence: p.evidence, source: r.repo ?? "", runId: r.id }];
71	    }
72	    return [];
73	  });
74	}
75	
76	/**
77	 * Latest run per repo within each (set, agent version). The held-out groups win; with none recorded,
78	 * whatever groups exist are shown under their own labels.
79	 */
80	function statGroups(real: RunSummary[]): StatGroup[] {
81	  const by = new Map<string, RunSummary[]>();
82	  for (const r of real) {
83	    const key = `${r.set ?? ""}|${r.agent_version ?? ""}`;
84	    by.set(key, [...(by.get(key) ?? []), r]);
85	  }
86	  const groups = [...by.entries()].map(([key, rs]): StatGroup => {
87	    const latest = latestPerRepo(rs);
88	    const skipped = latest.filter((r) => r.status === "fix_skipped_tests" || r.weakens_tests);
89	    // `verified` may be absent from the list; the status already says whether the clean container passed.
90	    const verified = latest.filter(
91	      (r) => !skipped.includes(r) && (r.verified ?? (r.status === "runs" || r.status === "runs_with_gaps" || r.status === "fix_awaiting_approval")),
92	    );
93	    const times = verified.filter((r) => r.fix_kind && r.duration_s != null).map((r) => r.duration_s as number);
94	    return {
95	      key,
96	      label: runTag(rs[0]) ?? "Earlier runs, set not recorded",
97	      set: rs[0].set ?? null,
98	      version: rs[0].agent_version ?? null,
99	      repos: latest.length,
100	      verified: verified.length,
101	      skipped: skipped.length,
102	      medianVerifiedS: median(times),
103	    };
104	  });
105	  const heldout = groups.filter((g) => g.set === "heldout");
106	  return (heldout.length ? heldout : groups).sort((a, b) =>
107	    (a.version ?? "").localeCompare(b.version ?? "", "en", { numeric: true }),
108	  );
109	}
110	
111	export function useLandingData(): LandingData {
112	  const { data: runs, loading, error } = useRuns();
113	  const list = useMemo(() => runs ?? [], [runs]);
114	  const featuredSummary = useMemo(() => pickFeatured(list), [list]);
115	  const { data: featured } = useRun(featuredSummary?.id ?? null);
116	
117	  return useMemo(() => {
118	    const f = featuredSummary;
119	    const before = f
120	      ? [...list].reverse().find((r) => r.repo === f.repo && r.path === f.path && r.id !== f.id && r.status !== "checking") ?? null
121	      : null;
122	    const real = list.filter((r) => r.status !== "checking");
123	    return {
124	      loading,
125	      error,
126	      runs: list,
127	      featured,
128	      featuredSummary: f,
129	      before,
130	      latest: latestPerRepo(list),
131	      problems: findProblems(real),
132	      stats: statGroups(real),
133	    };
134	  }, [list, featured, featuredSummary, loading, error]);
135	}
