import math


def hex2rgb(h):
    h = h.lstrip('#')
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def lin(c):
    c /= 255
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def Y(rgb):
    r, g, b = [lin(x) for x in rgb]
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def wcag(a, b):
    ya, yb = Y(a), Y(b)
    hi, lo = max(ya, yb), min(ya, yb)
    return (hi + .05) / (lo + .05)


def apca(txt, bg):
    def f(rgb):
        r, g, b = [(x / 255) ** 2.4 for x in rgb]
        y = 0.2126729 * r + 0.7151522 * g + 0.0721750 * b
        return y if y >= 0.022 else y + (0.022 - y) ** 1.414
    yt, yb = f(txt), f(bg)
    if yb > yt:
        s = (yb ** 0.56 - yt ** 0.57) * 1.14
        return (0 if s < 0.1 else s - 0.027) * 100
    s = (yb ** 0.65 - yt ** 0.62) * 1.14
    return (0 if s > -0.1 else s + 0.027) * -100


def oklch(L, C, h):
    a = C * math.cos(math.radians(h))
    b = C * math.sin(math.radians(h))
    l = (L + 0.3963377774 * a + 0.2158037573 * b) ** 3
    m = (L - 0.1055613458 * a - 0.0638541728 * b) ** 3
    s = (L - 0.0894841775 * a - 1.2914855480 * b) ** 3
    r = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s
    g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s
    bl = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s

    def e(x):
        x = max(0, min(1, x))
        return round(255 * (12.92 * x if x <= 0.0031308 else 1.055 * x ** (1 / 2.4) - 0.055))
    return (e(r), e(g), e(bl))


def hx(c):
    return '#%02X%02X%02X' % c


def over(fg, a, bg):
    return tuple(round(fg[i] * a + bg[i] * (1 - a)) for i in range(3))


if __name__ == '__main__':
    for L, C in [(0.50, 0.17), (0.48, 0.17), (0.45, 0.17)]:
        print('light approval', L, C, hx(oklch(L, C, 295)))
    for L, C in [(0.80, 0.10), (0.82, 0.10), (0.84, 0.10)]:
        print('dark approval', L, C, hx(oklch(L, C, 295)))

